#include <iostream>

int main() {
    int a = 5;  // First operand
    int b = 3;  // Second operand
    int c = 2;  // Third operand

    // Without parentheses: follows default precedence
    int result1 = a + b * c;  // Evaluates as a + (b * c) = 5 + (3 * 2) = 11

    // With parentheses: overrides precedence
    int result2 = (a + b) * c;  // Evaluates as ((a + b) * c) = (5 + 3) * 2 = 16

    std::cout << "Result without parentheses: " << result1 << std::endl;
    std::cout << "Result with parentheses: " << result2 << std::endl;
    return 0;
}
